package com.inventra.backend.controller; import com.inventra.backend.dto.StockMovementResponse; import com.inventra.backend.service.StockMovementService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/stock-movements") public class StockMovementController {private final StockMovementService s;public StockMovementController(StockMovementService s){this.s=s;}@GetMapping public List<StockMovementResponse> all(){return s.all();}@GetMapping("/products/{productId}") public List<StockMovementResponse> product(@PathVariable String productId){return s.product(productId);}@GetMapping("/warehouses/{warehouseId}") public List<StockMovementResponse> warehouse(@PathVariable String warehouseId){return s.warehouse(warehouseId);}}
